const icon=(name,cls='')=>`<svg viewBox="0 0 24 24" aria-hidden="true" class="icon ${cls}">${icons[name]||icons.info}</svg>`;
const btn=(action,label,ico,cls='',disabled=false,extra='')=>`<button type="button" data-act="${action}" class="${cls}" ${disabled?'disabled':''} ${extra}>${ico?icon(ico):''}${label}</button>`;
const iconBtn=(action,label,ico,disabled=false)=>btn(action,'',ico,'icon-button quiet',disabled,`aria-label="${esc(label)}" title="${esc(label)}"`);
function notify(message,error=false){clearTimeout(toastTimer);document.querySelector('#notifications').innerHTML=`<div class="toast ${error?'error':''}">${esc(message)}</div>`;toastTimer=setTimeout(()=>document.querySelector('#notifications').replaceChildren(),error?7000:3500);}
async function workspaceFetch(path,options){
  try{return await fetch(path,options);}
  catch{throw new Error('Cannot reach the local workspace. Check that VOLT-FORGE is running, then try again.');}
}
async function api(operation,args={},retry=true){
  const r=await workspaceFetch('/api/studio',{method:'POST',headers:{'Content-Type':'application/json','X-Voltforge-Token':S.token},body:JSON.stringify({operation,arguments:args})});
  // A restarted editor issues a new session token. Fetch it and try once more.
  if(r.status===403&&retry){const session=await workspaceFetch('/api/session').then(x=>x.json());S.token=session.result.token;return api(operation,args,false);}
  let value;try{value=await r.json();}catch{throw new Error('The connection was interrupted. Reopen this design to check whether the change was saved before retrying.');}
  if(!r.ok||value.status!=='ok')throw new Error(value.error?.message||'This action could not finish. Try again.');return value.result;
}
function dirty(){S.dirty=true;S.saveError=false;clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist().catch(e=>notify(e.message,true)),700);updateSaveStatus();}
function updateSaveStatus(){const el=document.querySelector('#save-status');if(el)el.textContent=S.saveError?'Save failed':S.saving?'Saving…':S.dirty?'Unsaved changes':'Saved';}
async function persist(){
  clearTimeout(saveTimer);
  if(savePromise){await savePromise;if(S.dirty)return persist();return;}
  if(!S.doc||!S.dirty)return;
  const designId=S.doc.id,graph=clone(S.graph),settings=clone(S.settings),version=S.doc.version;
  S.dirty=false;S.saving=true;updateSaveStatus();
  savePromise=api('save',{design_id:designId,version,graph,settings}).then(doc=>{
    if(S.doc?.id!==designId)return;
    S.doc=doc;S.saveError=false;
    if(S.test)S.test.current=doc.history.find(t=>t.id===S.test.id)?.current??false;
    const check=document.querySelector('#circuit-check');if(check)check.outerHTML=readinessLabel();
    const cost=document.querySelector('#live-cost');if(cost)cost.textContent=costLabel(doc.parts);
    const live=document.querySelector('#design-live');if(live)live.innerHTML=warningList(doc.readiness.warnings);
  }).catch(e=>{if(S.doc?.id===designId){S.dirty=true;S.saveError=true;}throw e;}).finally(()=>{S.saving=false;savePromise=null;updateSaveStatus();});
  await savePromise;
}
function snapshot(){return {graph:clone(S.graph),settings:clone(S.settings)};}
function mutate(fn,{renderNow=true}={}){S.history.push(snapshot());fn();dirty();if(renderNow)render();}
function readinessLabel(){const ok=S.doc?.readiness?.ready&&!S.dirty;return `<span id="circuit-check" class="circuit-check ${ok?'':'incomplete'}"><span class="status-dot"></span>${S.dirty?'Checking your design…':ok?'Ready to test':S.doc?.readiness?.structural_ready?'Review the test setup':'Finish your connections'}</span>`;}
function header(){return `<header class="topbar"><button class="brand" data-act="home" aria-label="VOLT-FORGE home"><span class="brand-mark">${icon('logo')}</span>VOLT-FORGE</button>${S.doc?`<span class="top-divider"></span><button class="project-name" data-act="rename" title="Rename design">${esc(S.graph.name)}</button><span id="save-status" class="save-status">${S.saving?'Saving…':S.dirty?'Unsaved changes':'Saved'}</span><nav aria-label="Workspace steps" class="workspace-nav">${['build','test','results','limits'].map(v=>btn(v==='limits'?'limits':'view:'+v,v==='limits'?'Find limits':v[0].toUpperCase()+v.slice(1),null,(S.view===v||(v==='results'&&['whatif','compare'].includes(S.view)))?'active':'')).join('')}</nav>`:''}<div class="top-actions">${btn('designs','My designs','folder','quiet designs-button')}${btn('help','Help','help','quiet help-button')}${btn('ai','AI copilot','spark','copilot-button '+(S.ai?'active':''),false,`aria-expanded="${S.ai}"`)}</div></header>`;}
function home(){const designs=S.catalog?.designs||[];return `<main id="main" class="home"><section class="home-top"><div class="home-copy"><h1>Build a battery.<br>Understand what changes.</h1><p>Connect cells, test your design and see how each decision changes its behaviour.</p><div class="home-buttons">${btn(tour.state.seen?'example':'tour:start',tour.state.seen?'Open four-cell example':'Try the guided example','play','primary')}${btn('new','New design','plus')}${!tour.state.seen?btn('tour:dismiss',"I'll explore on my own",null,'text-button'):''}</div></div>${heroBattery()}</section><form id="home-chat" class="home-ai">${icon('spark')}<label for="home-prompt" class="sr-only">Describe a battery design</label><input id="home-prompt" name="prompt" placeholder="Or describe a design to the AI copilot…" autocomplete="off" maxlength="4000"><button class="primary" type="submit" aria-label="Ask AI copilot">${icon('arrow')}</button></form>${designs.length?`<section class="recent-designs"><div class="section-heading"><h2>Continue a design</h2>${designs.length>3?btn('designs','View all',null,'text-button'):''}</div><div class="design-list">${designs.slice(0,3).map(designRow).join('')}</div></section>`:''}<p class="home-foot">Your designs are saved on this computer.</p></main>`;}
function designRow(d){return `<button class="design-item" data-act="open:${esc(d.id)}"><span class="design-glyph">${icon('battery')}</span><span><span class="design-title">${esc(d.name)}</span><span class="design-meta">${d.cells} ${d.cells===1?'cell':'cells'}${d.tests?' · '+d.tests+' saved '+(d.tests===1?'test':'tests'):''}</span></span>${icon('chevron','chevron')}</button>`;}
function build(){const g=S.graph,first=!g.cells.length;return `<main id="main" class="build-area"><div class="canvas-heading"><div><h1>${esc(g.name)}</h1><p>${g.cells.length?`${g.cells.length} ${g.cells.length===1?'cell':'cells'} · your editable battery design · <span id="live-cost">${esc(costLabel(S.doc.parts))}</span>`:'An empty canvas for your battery'}</p></div><div class="canvas-heading-actions"><div class="segment" aria-label="Design view">${btn('mode:assembly','Assembly',null,S.mode==='assembly'?'active':'')}${btn('mode:circuit','Circuit',null,S.mode==='circuit'?'active':'')}</div>${btn('view:test','Test this design','play','primary',S.running)}</div></div><div id="design-live">${warningList(S.doc.readiness.warnings)}</div><section class="canvas-stage" aria-label="Battery design canvas"><div class="canvas-topline"><div class="tools">${btn('library','Add cell','plus','add-cell-button',g.cells.length>=16)}<span class="tool-divider"></span>${btn('tool:select','<span class="tool-name">Select</span>','pointer',S.tool==='select'?'active':'',false,'title="Select and move a cell"')}${btn('tool:connect','<span class="tool-name">Connect</span>','wire',S.tool==='connect'?'active':'',!g.cells.length,'title="Connect two terminals"')}<span class="tool-divider"></span>${iconBtn('undo','Undo','undo',!S.history.undo.length)}${iconBtn('redo','Redo','redo',!S.history.redo.length)}${iconBtn('delete','Delete selected component','trash',!S.selected||S.selected.includes(':'))}</div>${iconBtn('help','Canvas guide','help')}</div><div class="canvas-model" id="canvas-model">${renderCanvas(g,{load:loadBlockModel(S.doc.application,S.settings),mode:S.mode,selected:S.selected,tool:S.tool,pending:S.pending})}${first?`<div class="blank-canvas">${icon('battery')}<h2>Start with a cell</h2><p>Add cells, then connect their positive and negative terminals.</p>${btn('library','Add your first cell','plus','primary')}</div>`:''}${S.onboarding&&g.cells.length?`<div class="floating-helper"><strong>Try changing one cell.</strong>Click a cell to change its starting charge. Use Connect to wire any two terminals.${btn('dismiss-guide','Got it',null,'text-button')}</div>`:''}</div><div class="canvas-bottomline"><span class="canvas-hint">${icon(S.tool==='connect'?'wire':'pointer')}${S.tool==='connect'?(S.pending?'Choose the second terminal to finish the connection.':'Click a positive or negative terminal to start a connection.'):'Select a cell to edit it. Drag to arrange your design.'}</span>${readinessLabel()}</div></section></main>`;}
function commonThermal(key){const values=S.graph.cells.map(cell=>S.graph.thermal.cell_parameters?.[cell.id]?.[key]??modelFor(cell).thermal_defaults?.[key]??S.graph.thermal[key]);return values.length&&values.every(v=>Math.abs(v-values[0])<1e-9)?values[0]:'';}
function testSetup(){const s=S.settings,p=s.profile[0],duration=s.profile.at(-1).end_s,multi=s.profile.length>1;return `<main id="main" class="page-wrap"><div class="page-intro"><h1>Put your design to the test</h1><p>Choose the load, how long it runs and the room temperature.</p></div>${applicationLine(S.doc.application)}<div class="test-layout"><form id="test-form" class="test-form"><h2>Test conditions</h2>${multi?'<p class="helper">This test uses several load intervals. Edit their durations and currents below.</p>':''}<div class="field"><label for="test-direction">What should the battery do?</label><select id="test-direction" name="direction" ${multi?'disabled':''}><option value="discharge" ${p.current_A>=0?'selected':''}>Power something · discharge</option><option value="charge" ${p.current_A<0?'selected':''}>Recharge the cells</option><option value="rest" ${p.current_A===0?'selected':''}>Rest with no external load</option></select></div><div class="field-row"><div class="field"><label for="test-current">Battery current</label><div class="input-unit"><input id="test-current" name="current" ${multi?'disabled':''} type="number" min="0" max="200" step="any" value="${Math.abs(p.current_A)}" required><span>A</span></div><p>The total current at the battery output.</p></div><div class="field"><label for="test-duration">Test duration</label><div class="input-unit"><input id="test-duration" name="duration" ${multi?'disabled':''} type="number" min="0.02" max="1440" step="any" value="${duration/60}" required><span>min</span></div><p>Choose the length of your experiment.</p></div></div><div class="field"><label for="test-ambient">Room temperature</label><div class="input-unit"><input id="test-ambient" name="ambient" type="number" min="-40" max="100" step="any" value="${s.ambient_C}" required><span>°C</span></div></div><details><summary>Change the load during the test</summary><div><p class="helper">Add intervals for changing demand, charging or rest. Negative current recharges; zero current rests.</p><div id="load-intervals">${s.profile.map((r,i)=>intervalRow(r,i)).join('')}</div>${btn('add-interval','Add interval','plus','text-button')}<p class="helper">When intervals are present, their durations and currents set the test.</p></div></details><details class="test-targets"><summary>Set targets to check</summary><div><p class="helper">Use your design requirements. An empty field leaves that check off.</p><div class="field-row"><div class="field"><label for="target-temperature">Maximum cell temperature</label><div class="input-unit"><input id="target-temperature" name="limit_temperature" type="number" step="any" value="${s.limits.temperature_C??''}" placeholder="Optional"><span>°C</span></div></div><div class="field"><label for="target-current">Maximum cell current</label><div class="input-unit"><input id="target-current" name="limit_current" type="number" min="0" step="any" value="${s.limits.current_A??''}" placeholder="Optional"><span>A</span></div></div></div><div class="field-row"><div class="field"><label for="target-voltage">Minimum battery voltage</label><div class="input-unit"><input id="target-voltage" name="limit_voltage" type="number" min="0" step="any" value="${s.limits.min_voltage_V??''}" placeholder="Optional"><span>V</span></div></div><div class="field"><label for="target-imbalance">Maximum current difference</label><div class="input-unit"><input id="target-imbalance" name="limit_imbalance" type="number" min="0" step="any" value="${s.limits.imbalance_pct??''}" placeholder="Optional"><span>%</span></div></div></div><p class="helper">The percentage is the largest cell-current spread divided by the mean current. It applies to parallel branches.</p></div></details>${protectionForm(s)}<details><summary>Solver and heat transfer</summary><div><div class="field-row"><div class="field"><label for="test-step">Time step <small>(s)</small></label><input id="test-step" name="step" type="number" min="0.01" max="10" step="any" value="${s.dt_s}" required><p>Smaller steps resolve fast electrical changes.</p></div><div class="field"><label for="heat-capacity">Cell heat capacity <small>(J/°C)</small></label><input id="heat-capacity" name="heat_capacity" type="number" min="1" max="10000" step="any" value="${commonThermal('heat_capacity_J_K')}" placeholder="Varies by cell"><p>Energy needed to warm one cell by 1 °C. Editing sets all cells.</p></div></div><div class="field"><label for="cooling-conductance">Cooling to the room <small>(W/°C per cell)</small></label><input id="cooling-conductance" name="cooling" type="number" min="0" max="100" step="any" value="${commonThermal('ambient_conductance_W_K')}" placeholder="Varies by cell"><p>Heat removed per degree above room temperature. The default comes from one published test rig, and published estimates span about 0.076 to 0.18. It is not a still-air value. Editing sets all cells.</p>${btn('cooling-low','Try low cooling (0.076, an assumption)',null,'text-button')}</div>${btn('thermal-contacts','Edit cell-to-cell heat contacts','edit','text-button')}</div></details>${S.testError?`<div class="error-inline" role="alert">${esc(S.testError)}</div>`:''}<div class="test-action">${S.running?`<div class="running-state"><div class="loading-mark"></div>Calculating your circuit…</div>`:'<span class="helper">Electrical + thermal simulation</span>'}<button type="submit" class="primary" ${S.running?'disabled':''}>${icon('play')}${S.running?'Testing…':'Run test'}</button></div></form><aside class="test-summary"><h2>${esc(S.graph.name)}</h2><div class="battery-preview">${renderCanvas(S.graph,{mode:'assembly',prefix:'test',load:loadBlockModel(S.doc.application,S.settings),interactive:false})}</div>${profileSummary(s.profile)}<dl><div><dt>Cells</dt><dd>${S.graph.cells.length}</dd></div><div><dt>Starting charge</dt><dd>${startingRange('charge_pct','%')}</dd></div><div><dt>Starting temperature</dt><dd>${startingRange('temperature_C',' °C')}</dd></div><div><dt>Connections</dt><dd>${S.graph.connections.length}</dd></div></dl>${btn('view:build','Edit the design','back','text-button')}${!S.doc.readiness.ready?`<div class="info-inline">${esc(S.doc.readiness.message)}</div>`:''}${warningList(S.doc.readiness.warnings)}${partsPanel(S.doc.parts)}</aside></div></main>`;}
function intervalRow(p,i){return `<div class="interval-row" data-interval="${i}"><div><label for="interval-duration-${i}">Interval ${i+1} · minutes</label><input id="interval-duration-${i}" class="interval-duration" type="number" min="0.001" step="any" value="${(p.end_s-p.start_s)/60}"></div><div><label for="interval-current-${i}">Current (A)</label><input id="interval-current-${i}" class="interval-current" type="number" min="-200" max="200" step="any" value="${p.current_A}"></div>${iconBtn('remove-interval:'+i,'Remove interval '+(i+1),'trash',S.settings.profile.length===1)}</div>`;}
function startingRange(key,unit){const v=S.graph.cells.map(c=>c[key]);if(!v.length)return '—';return (Math.min(...v)===Math.max(...v)?fmt(v[0],0):`${fmt(Math.min(...v),0)}–${fmt(Math.max(...v),0)}`)+unit;}
function results(){if(!S.test)return `<main id="main" class="page-wrap"><div class="empty-results">${icon('chart')}<h1>See what your design does</h1><p>Run a test to explore each cell’s current, temperature, voltage and charge.</p>${btn('view:test','Set up a test','play','primary')}${S.doc.history.length?`<div class="field">${historySelect()}</div>`:''}</div></main>`;
 const t=S.test,m=t.summary.metrics,charging=t.settings.profile.every(p=>p.current_A<=0)&&t.settings.profile.some(p=>p.current_A<0),field=chartFields[S.metric],names=Object.fromEntries(t.graph.cells.map(c=>[c.id,c.name]));
 return `<main id="main" class="page-wrap"><div class="results-heading"><div><h1>Your test results</h1><p>${esc(t.name)}${t.name===t.design_name?'':' · '+esc(t.design_name)} <span class="status-pill ${t.current?'estimate':'old'}">${t.current?'Simulation': 'Earlier design version'}</span></p></div><div class="result-actions">${historySelect()}${btn('export','Export','download','',false,'title="Download report, data and reproducible model"')}</div></div>${protectionResult(t)}${t.stop?`<div class="info-inline">The test stopped at ${timeLabel(m.duration_s)}. ${esc(t.stop.message)}</div>`:''}${!t.current?`<div class="info-inline">The design, test settings or model version has changed since this result. ${btn('view:test','Test the current design',null,'text-button')}</div>`:''}${applicationLine(t.summary.application)}${warningList(t.summary.design_warnings)}${verdictRows(t,timeLabel)}<p class="helper verdict-foot">${charging?'Energy received':'Energy delivered'} ${fmt(charging?m.received_energy_Wh:m.delivered_energy_Wh,2)} Wh over ${timeLabel(m.duration_s)}.${t.summary.thermal_assumptions?.some(a=>a.status==='Assumed heat model')?' Temperature uses an assumed heat model.':''}${t.summary.charging?' '+esc(t.summary.charging.note):''}</p>${partsPanel(t.parts)}<section class="result-body"><div class="chart-toolbar"><h2>${field.title}</h2><div class="segment" aria-label="Result to explore">${['current','temperature','voltage','charge'].map(k=>btn('metric:'+k,k[0].toUpperCase()+k.slice(1),null,S.metric===k?'active':'')).join('')}</div></div><div class="chart-area" id="chart-area">${chartSvg(t,S.metric,S.index,S.hidden)}<div id="chart-tooltip" class="chart-tooltip"></div></div><div class="chart-legend">${t.graph.cells.map((c,i)=>btn('legend:'+i,`<span class="series-dot series-${i%4}"></span>${esc(c.name)}`,null,S.hidden.has(i)?'muted-series':'',false,`aria-pressed="${!S.hidden.has(i)}"`)).join('')}</div><div class="chart-time-control"><label for="result-time" class="sr-only">Inspect test time</label><span id="time-readout" class="time-readout">${timeLabel(t.rows[S.index].time_s)}</span><input id="result-time" type="range" min="0" max="${t.rows.length-1}" value="${S.index}" step="1" aria-valuetext="${timeLabel(t.rows[S.index].time_s)}"><span>${timeLabel(m.duration_s)}</span></div><div class="insights">${icon('spark')}<div><h3>What this test shows</h3>${t.summary.insights.slice(0,2).map(i=>`<p>${esc(i)}</p>`).join('')}${btn('ask-results','Explore these results with AI','arrow','text-button')}</div></div></section><div class="results-next">${btn('limits','Where does it break?','load')}${btn('smallest','Find the smallest design','battery')}${btn('compare','Compare designs','compare')}${btn('show-assembly','See values on the battery','battery')}</div>${S.showAssembly?`<div class="results-assembly" id="results-assembly">${renderCanvas(t.graph,{mode:S.mode,selected:S.selected,layer:S.metric,row:t.rows[S.index],prefix:'results'})}</div>`:''}${targetChecks(t)}<div class="details-link">${btn('model','About this model',null,'text-button')}${btn('verification','Calculation checks',null,'text-button')}</div></main>`;}
function historySelect(){return `<label class="sr-only" for="test-history">Saved tests</label><select id="test-history" class="history-select" aria-label="Saved tests"><option value="">Choose a saved test</option>${S.doc.history.map(t=>`<option value="${esc(t.id)}" ${S.test?.id===t.id?'selected':''}>${esc(t.name)}${t.current?'':' · earlier version'}</option>`).join('')}</select>`;}
function targetChecks(t){const labels={temperature_C:'Cell temperature',current_A:'Cell current',min_voltage_V:'Battery voltage',imbalance_pct:'Current difference'},units={temperature_C:'°C',current_A:'A',min_voltage_V:'V',imbalance_pct:'%'};return t.summary.checks.length?`<details><summary>Your design targets</summary>${t.summary.checks.map(c=>`<div class="check-row"><span>${labels[c.metric]}<p>${c.metric==='min_voltage_V'?'Minimum':'Maximum'} ${fmt(c.target)} ${units[c.metric]}</p></span><span class="check-value ${c.status==='within_target'&&t.status==='completed'?'within':c.status==='exceeded'?'exceeded':''}">${c.status==='not_modeled'?'Not modeled':c.status==='not_applicable'?'Not applicable':`${fmt(c.value)} ${units[c.metric]} · ${c.status==='exceeded'?'Target exceeded':c.status==='inconclusive'||t.status!=='completed'?(t.summary.service&&!t.summary.service.requested_demand_met?'Requested duty not met':'Test incomplete'):'Within target'}`}</span></div>`).join('')}</details>`:'';}
function whatif(){return `<main id="main" class="page-wrap"><div class="page-intro">${btn('view:results','Back to results','back','text-button')}<h1>Change one thing. See the difference.</h1><p>Each what-if creates a separate design and runs a real test. Your original stays available for comparison.</p></div><div class="whatif-options"><div class="whatif-option">${icon('load')}<div><h2>Ask for more power</h2><p>Increase the battery current by 50%. See which cell works hardest and how its temperature changes.</p></div>${btn('scenario:load','Try 1.5× load','arrow','',S.running)}</div><div class="whatif-option">${icon('wire')}<div><h2>Make one connection worse</h2><p>Add 3 mΩ to the first connection. Explore how a worn contact changes the paths that current takes.</p></div>${btn('scenario:connection','Try connection wear','arrow','',S.running||!S.graph.connections.length)}</div><div class="whatif-option">${icon('battery')}<div><h2>Start one cell less charged</h2><p>Lower the first cell’s starting charge by 10 percentage points. See how it interacts with the others.</p></div>${btn('scenario:charge','Try uneven charge','arrow','',S.running||!S.graph.cells.length)}</div></div>${S.running?'<div class="field running-state"><div class="loading-mark"></div>Testing the changed design…</div>':''}<div class="details-link">${btn('view:test','Choose your own test conditions','edit','text-button')}${btn('ai','Ask the AI for another experiment','spark','text-button')}</div></main>`;}
function comparison(){const all=S.allTests||[];return `<main id="main" class="page-wrap"><div class="page-intro">${btn('view:results','Back to results','back','text-button')}<h1>Compare two tests</h1><p>Look at the design changes and their consequences under the same conditions.</p></div>${all.length<2?`<p>Run a second design or try a what-if to create an alternative.</p>${btn('whatif','Try a what-if','load','primary')}`:`<form id="compare-form" class="comparison-controls"><div><label for="compare-left">First design and test</label><select id="compare-left" name="left">${all.map(t=>`<option value="${t.id}" ${S.compareLeft===t.id?'selected':''}>${esc(actualTestName(t))}</option>`).join('')}</select></div><div><label for="compare-right">Second design and test</label><select id="compare-right" name="right">${all.map(t=>`<option value="${t.id}" ${S.compareRight===t.id?'selected':''}>${esc(actualTestName(t))}</option>`).join('')}</select></div><button type="submit" class="primary">Compare</button></form>`}${S.comparison?comparisonResults(S.comparison):''}</main>`;}
function comparisonResults(c){const [a,b]=c.tests,am=a.summary.metrics,bm=b.summary.metrics;const fields=[['Warmest cell','peak_temperature_C','°C'],['Largest cell current','peak_cell_current_A','A'],['Energy delivered','delivered_energy_Wh','Wh'],['Energy received','received_energy_Wh','Wh'],['Net energy output','net_energy_Wh','Wh'],['Lowest battery voltage','minimum_voltage_V','V'],['Temperature difference','maximum_temperature_spread_C','°C'],['Test duration','duration_s','s'],...([am.conductor_mass_g,bm.conductor_mass_g].some(v=>v!=null)?[['Dimensioned conductor mass','conductor_mass_g','g']]:[])];return `<div class="compare-notice ${!c.identical_test_conditions||!c.comparable_duration?'info-inline':''}">${esc(c.note)}${!c.comparable_duration?' The tests stopped at different times, so energy totals cover different durations.':''}</div>${c.design_changes?.length?`<details><summary>What changed between these designs</summary><ul class="change-list">${c.design_changes.map(d=>`<li>${esc(friendlyChange(d,c.tests))}</li>`).join('')}</ul></details>`:''}${c.settings_changes?.length?`<details><summary>What changed in the test settings</summary><ul class="change-list">${c.settings_changes.map(d=>`<li>${esc(friendlyChange(d,c.tests))}</li>`).join('')}</ul></details>`:''}<div class="compare-designs">${c.tests.map((t,i)=>`<div><h3>${esc(t.design_name)}</h3>${renderCanvas(t.graph,{mode:S.mode,prefix:'compare'+i})}</div>`).join('')}</div><div class="field"><table class="compare-table"><thead><tr><th>Result</th><th>First test</th><th>Second test</th><th>Difference</th></tr></thead><tbody>${tradeoffRows(a,b,deltaLabel)}${fields.map(([label,key,unit])=>`<tr><td>${label}</td><td>${fmt(am[key],2)} <small>${unit}</small></td><td>${fmt(bm[key],2)} <small>${unit}</small></td><td>${deltaLabel(c.deltas[key])} <small>${unit}</small></td></tr>`).join('')}</tbody></table></div><p class="helper">${c.single_factor_comparison?'One design input changed under matching model and test settings.':'Review the input changes and test conditions before attributing a difference to the design.'}</p>${btn('ask-comparison','Ask AI about this comparison','spark','text-button')}`;}
function selectedPanel(){const g=S.view==='results'&&S.test?S.test.graph:S.graph,c=g.cells.find(c=>c.id===S.selected),w=g.connections.find(w=>w.id===S.selected),terminal=S.selected?.includes(':')?S.selected:null;const title=c?'Selected cell':w?'Selected connection':'Selected terminal';let body='';
 if(c){const i=g.cells.indexOf(c),row=S.view==='results'&&S.test?S.test.rows[S.index]:null;body=`<div class="selection-card">${thumbnail(c)}<div><h2>${esc(c.name)}</h2><p>${esc(modelFor(c).family||'Custom')} battery cell</p><p class="sample-label">${esc(S.catalog.library.find(m=>m.key===c.model)?.name||'Measured-data cell model')}</p></div></div>${row?`<h3>At ${timeLabel(row.time_s)}</h3><div class="panel-section reading-grid"><div><span>Current</span><strong>${fmt(row.cell_current_A[i],2)} <small>A</small></strong></div><div><span>Temperature</span><strong>${row.temperature_C[i]===null?'Not modeled':fmt(row.temperature_C[i])+' <small>°C</small>'}</strong></div><div><span>Voltage</span><strong>${fmt(row.cell_voltage_V[i],3)} <small>V</small></strong></div><div><span>Charge left</span><strong>${fmt(row.charge_pct[i])}<small>%</small></strong></div></div>${btn('edit-selected','Edit this cell','edit','text-button')}`:`<div class="field"><label for="cell-charge">Starting charge</label><div class="charge-control"><input id="cell-charge-range" type="range" ${chargeLimits(c)} step="1" value="${c.charge_pct}" aria-label="Starting charge"><div class="input-unit"><input id="cell-charge" type="number" ${chargeLimits(c)} step="1" value="${c.charge_pct}" data-cell-field="charge_pct" aria-label="Starting charge percent"></div><span>%</span></div><p>How full this cell is when the test begins.</p></div><div class="field"><label for="cell-temperature">Starting temperature</label><div class="input-unit"><input id="cell-temperature" type="number" ${cellTempLimits(c)} step="0.1" value="${c.temperature_C}" data-cell-field="temperature_C"><span>°C</span></div><p>The cell’s temperature at the start, which can differ from the room.</p></div><div class="field"><label for="cell-name">Cell name</label><input id="cell-name" maxlength="60" value="${esc(c.name)}" data-cell-field="name"></div><details><summary>Cell model and data</summary><p>Choose a battery type or keep an original fitted sample. Each model has its own source and operating range.</p><div class="field"><label for="cell-model">Battery model</label><select id="cell-model" data-cell-field="model">${S.catalog.library.map(m=>`<option value="${m.key}" ${m.key===c.model?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><dl><div><dt>Model capacity</dt><dd>${fmt(S.catalog.library.find(m=>m.key===c.model)?.capacity_Ah,2)} Ah</dd></div><div><dt>Reference resistance</dt><dd>${fmt(S.catalog.library.find(m=>m.key===c.model)?.resistance_mohm,1)} mΩ</dd></div></dl><p>Capacity describes stored charge. Resistance describes the immediate voltage drop and heat under load.</p>${modelFor(c).source_url?`<p><a href="${esc(modelFor(c).source_url)}" target="_blank" rel="noopener">View this model’s source</a></p>`:'<p>Source: your own parameters. Independent assessment pending.</p>'}${modelFor(c).custom&&modelFor(c).basic?btn('custom-version:'+c.model,'Create a new cell version','edit','text-button'):''}</details>${modelFor(c).custom&&!modelFor(c).thermal_available?'<p class="helper">This custom cell has no thermal data. Its temperature is held at the starting value for the electrical estimate.</p>':`<details><summary>Heating and cooling</summary><p>These values describe how this cell stores heat and releases it to the room.</p><div class="field"><label for="cell-heat-capacity">Heat capacity (J/°C)</label><input id="cell-heat-capacity" type="number" min="1" max="10000" step="any" value="${S.graph.thermal.cell_parameters?.[c.id]?.heat_capacity_J_K??modelFor(c).thermal_defaults?.heat_capacity_J_K??S.graph.thermal.heat_capacity_J_K}" data-cell-thermal="heat_capacity_J_K"><p>Energy needed to warm this cell by 1 °C.</p></div><div class="field"><label for="cell-cooling">Cooling to the room (W/°C)</label><input id="cell-cooling" type="number" min="0" max="100" step="any" value="${S.graph.thermal.cell_parameters?.[c.id]?.ambient_conductance_W_K??modelFor(c).thermal_defaults?.ambient_conductance_W_K??S.graph.thermal.ambient_conductance_W_K}" data-cell-thermal="ambient_conductance_W_K"><p>Heat released per degree above room temperature.</p></div></details>`}<details><summary>Initial electrical relaxation</summary><p>After changing load, a cell takes time to settle. Leave this at zero for the rested starting assumption.</p><div class="field"><label for="cell-polarization">Relaxation voltage (V)</label><input id="cell-polarization" type="number" min="-1" max="1" step="any" value="${c.polarization_V}" data-cell-field="polarization_V"></div></details>`}`;}
 else if(w){body=`<div class="terminal-preview">${icon('wire')}<strong>Electrical connection</strong></div><h2>${esc(describeConnection(g,w))}</h2><div class="field"><label for="wire-resistance">Connection resistance</label><div class="input-unit"><input id="wire-resistance" type="number" min="0" max="1000" step="0.1" value="${w.resistance_mohm}" data-wire-field="resistance_mohm" ${S.view==='results'||w.conductor?'disabled':''}><span>mΩ</span></div><p>Resistance makes current harder to pass and creates heat. A worn or poor contact usually has more resistance.</p></div>${S.view!=='results'?`${conductorEditor(w,S.catalog.conductor_reference)}<details><summary>Where this value comes from</summary><div class="field"><label for="wire-source">Source or assumption</label><textarea id="wire-source" data-wire-field="source" rows="3" maxlength="500">${esc(w.source)}</textarea></div></details>`:''}`;}
 else if(terminal){const [cid,pole]=terminal.split(':'),cell=g.cells.find(c=>c.id===cid);body=`<div class="terminal-preview"><span class="terminal-symbol">${pole==='p'?'+':'−'}</span><strong>${esc(cell?.name)} ${pole==='p'?'positive':'negative'}</strong></div><p>Connect this terminal to another cell, or use it as one of the battery’s external outputs.</p><div class="panel-section stack">${btn('connect-from','Connect from here','wire','primary')}${btn('output:positive','Use as positive battery output','plus')}${btn('output:negative','Use as negative battery output',null)}</div>${Object.values(g.output).includes(terminal)?`<p class="helper">This is a battery output. You can include the conductor route from this terminal to an external connector.</p>${conductorEditor({output:Object.keys(g.output).find(p=>g.output[p]===terminal),conductor:g.output_leads?.[Object.keys(g.output).find(p=>g.output[p]===terminal)]},S.catalog.conductor_reference)}`:''}`;}
 return `<aside class="side-panel"><div class="panel-header"><h2>${title}</h2>${iconBtn('close-panel','Close properties','close')}</div><div class="panel-content">${body}<div class="panel-section">${btn('ask-selected','Ask AI about this component','spark','text-button')}</div></div>${S.view!=='results'&& !terminal?`<div class="panel-footer">${btn('delete','Remove '+(c?'cell':'connection'),'trash','quiet danger-button')}</div>`:''}</aside>`;
}
function aiPanel(){const selected=S.graph?.cells.find(c=>c.id===S.selected)?.name|| (S.selected?.startsWith('wire')?'Selected connection':null);return `<aside class="side-panel ai-panel"><div class="panel-header"><div><h2>AI copilot</h2><div class="provider-label"><span class="status-dot"></span>${esc(S.catalog?.copilot.provider||'Local account connection')}</div></div>${iconBtn('close-ai','Close AI copilot','close')}</div><div class="chat-scroll" id="chat-scroll">${!S.messages.length?`<div class="chat-welcome">${icon('spark')}<h2>${S.doc?'Let’s work on your design.':'What would you like to build?'}</h2><p>${S.doc?'Ask about a cell, explore a result or describe a change. You review every proposed edit before applying it.':'Describe your battery, or start with an idea below. I’ll prepare an editable design for you to review.'}</p><div class="suggestions">${(S.doc?['Explain how this battery is connected','What should I test first?','Create a four-cell series alternative']:['Build a four-cell parallel design','Help me choose a first experiment','Explain series and parallel simply']).map(q=>btn('suggest:'+q,esc(q),'arrow')).join('')}</div></div>`:''}${S.messages.map(m=>`<div class="chat-message ${m.role}">${m.role==='assistant'?`<div class="message-source">${icon('spark')}VOLT-FORGE copilot</div>${messageHtml(m.content)}`:esc(m.content)}${m.proposal?proposalHtml(m.proposal):''}</div>`).join('')}${S.chatBusy?'<div class="ai-thinking"><div class="loading-mark"></div>Working with your design…</div>':''}${S.chatError?`<div class="chat-error" role="alert">${esc(S.chatError)}</div>`:''}</div><div class="chat-context">${icon('battery')}${esc(selected||S.graph?.name||'New battery design')}${S.view==='compare'&&S.comparison?' · two saved tests included':S.test&&S.view==='results'?' · test results included':''}</div><form id="chat-form" class="chat-form"><div class="chat-compose"><label for="chat-input" class="sr-only">Ask the AI copilot</label><textarea id="chat-input" name="message" placeholder="Ask a question or describe a change…" rows="2" maxlength="4000" ${S.chatBusy?'disabled':''}>${esc(chatDraft)}</textarea><div class="chat-compose-footer"><small>Edits are previewed before applying.</small><button type="submit" class="primary" ${S.chatBusy?'disabled':''} aria-label="Send to AI copilot">${icon('send')}</button></div></div></form></aside>`;}
function messageHtml(content){return esc(content).split(/\n\s*\n/).map(p=>`<p>${p.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')}</p>`).join('');}
function proposalHtml(p){return p.applied?`<div class="proposal applied">${icon('check')} ${p.created?'Draft created on the canvas':'Changes applied'}</div>`:`<div class="proposal"><h3>Proposed changes</h3><ul>${p.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>${btn('apply:'+p.id,'Apply changes','check','primary')}</div>`;}
function focusKey(el){if(!el||!app.contains(el))return null;if(el.id)return '#'+CSS.escape(el.id);for(const key of ['act','cell','terminal','wire'])if(el.dataset?.[key])return `[data-${key}="${CSS.escape(el.dataset[key])}"]`;return null;}
let renderedView=null;
function render(){const active=document.activeElement,focus=focusKey(active);let caret=null;try{caret=active?.selectionStart??null;}catch{}const side=S.ai?aiPanel():S.doc&&S.selected?selectedPanel():'';app.innerHTML=header()+tourHtml()+`<div class="studio-layout ${side?'with-panel':''}"><div class="main-region">${!S.doc?home():S.view==='build'?build():S.view==='test'?testSetup():S.view==='limits'?failurePage():S.view==='whatif'?whatif():S.view==='compare'?comparison():results()}</div>${side}</div>`;bindCanvas();bindChart();placeGuidedPanel();if(S.ai){const scroll=document.querySelector('#chat-scroll');scroll.scrollTop=scroll.scrollHeight;}updateSaveStatus();const view=S.doc?S.view:'home';if(renderedView!==null&&renderedView!==view){const heading=app.querySelector('#main h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}else if(focus){const target=app.querySelector(focus);if(target){target.focus({preventScroll:true});if(caret!==null)try{target.setSelectionRange(caret,caret);}catch{}}}renderedView=view;}
function placeGuidedPanel(){const panel=document.querySelector('.side-panel'),guide=document.querySelector('#walkthrough');if(!panel)return;if(innerWidth<=780&&guide)panel.style.top=guide.getBoundingClientRect().bottom+'px';else panel.style.removeProperty('top');}
window.addEventListener('resize',placeGuidedPanel);
function showDialog(title,body){dialog.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2>${iconBtn('close-dialog','Close dialog','close')}</div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
let setup=newSetup();
function newDialog(){templateChoice='parallel';setup=newSetup();setupDialog();}
function setupDialog(){const s=setup,back=btn('setup-back','Back',null,'quiet');const name=s.preset==='pi5_gateway_backup'?'Pi 5 gateway backup':'My battery design';
 if(s.step<3)return showDialog(`Step ${s.step} of 3`,`${s.step===1?setupTypeStep(s):setupLoadStep(s)}<div class="dialog-footer">${s.step===1?btn('close-dialog','Cancel',null,'quiet'):back}${btn('setup-next','Next','arrow','primary')}</div>`);
 showDialog('Step 3 of 3',`<form id="new-form"><div class="field"><label for="new-name">Design name</label><input id="new-name" name="name" value="${esc(name)}" maxlength="100" required></div><div class="field"><label>Choose a starting point</label><div class="template-options">${templateOptions()}</div></div><div class="field"><label for="new-count">Number of cells</label><input id="new-count" name="count" type="number" min="1" max="16" value="4" required></div><div class="dialog-footer">${back}<button type="submit" class="primary">Create design ${icon('arrow')}</button></div></form>`);}
function readSetup(){const form=dialog.querySelector('#setup-load-form');if(form)setup=readSetupFields(form,setup);}
function templateOptions(){return [['parallel','parallel','Share the load','Cells side by side, connected in parallel.'],['series','series','Increase the voltage','Cells connected end to end, in series.'],['mixed','grid','Combine both','Pairs in series, with the pairs sharing the load.'],['blank','plus','Start from an empty canvas','Place and connect every cell yourself.']].map(([kind,ico,title,desc])=>`<button type="button" data-act="template:${kind}" class="template-option ${templateChoice===kind?'active':''}">${icon(ico)}<span><strong>${title}</strong><span>${desc}</span></span><span class="chosen"></span></button>`).join('');}
async function refreshCatalog(){const r=await workspaceFetch('/api/studio');const j=await r.json();if(j.status!=='ok')throw new Error(j.error?.message);S.catalog=j.result;setCellLibrary(S.catalog.library);}
function modelFor(cell){return S.catalog?.library.find(m=>m.key===cell.model)||{family:'Unavailable cell model',temperature_range_C:[-40,100],soc_range_pct:[0,100]};}
function cellTempLimits(cell){const b=modelFor(cell).temperature_range_C||[-40,100];return `min="${Math.ceil(b[0]*10)/10}" max="${Math.floor(b[1]*10)/10}"`;}
function chargeLimits(cell){const b=modelFor(cell).soc_range_pct||[15,95];return `min="${Math.ceil(b[0])}" max="${Math.floor(b[1])}"`;}
async function openDesign(id){const request=++navigationRequest;await persist();const doc=await api('open',{design_id:id});if(request!==navigationRequest)return;loadDoc(doc);dialog.close();render();}
function loadDoc(doc){contextEpoch++;S.doc=doc;S.graph=clone(doc.graph);S.settings=clone(doc.settings);S.view='build';S.selected=null;S.pending=null;S.tool='select';S.test=null;S.investigation=null;S.screenSelected=0;S.dirty=false;S.history=new History();S.testError=null;S.index=0;S.comparison=null;S.hidden.clear();S.messages=[];S.chatError=null;chatDraft='';}
async function createExample(){await persist();const doc=await api('create',{kind:'parallel',count:4,name:'Four-cell example'});loadDoc(doc);S.onboarding=false;render();await refreshCatalog();}
async function runTest(){
 const form=document.querySelector('#test-form');if(!form?.reportValidity())return;const data=new FormData(form);
 const designId=S.doc.id,epoch=contextEpoch;const draft=clone(S.settings),g=clone(S.graph),direction=data.get('direction');
 const intervals=[...form.querySelectorAll('[data-interval]')];
 if(intervals.length>1){let time=0;draft.profile=intervals.map(row=>{const end=time+Number(row.querySelector('.interval-duration').value)*60;const r={start_s:time,end_s:end,current_A:Number(row.querySelector('.interval-current').value)};time=end;return r;});}
 else draft.profile=[{start_s:0,end_s:Number(data.get('duration'))*60,current_A:direction==='rest'?0:Number(data.get('current'))*(direction==='charge'?-1:1)}];
 draft.ambient_C=Number(data.get('ambient'));draft.dt_s=Number(data.get('step'));const protection=readProtection(form);if(protection||'protection' in draft)draft.protection=protection;
 for(const [field,input] of [['temperature_C','limit_temperature'],['current_A','limit_current'],['min_voltage_V','limit_voltage'],['imbalance_pct','limit_imbalance']])draft.limits[field]=data.get(input)===''?null:Number(data.get(input));
 for(const [field,key] of [['heat_capacity','heat_capacity_J_K'],['cooling','ambient_conductance_W_K']]){const input=form.elements[field];if(input.value!==''&&input.dataset.edited==='true'){g.thermal[key]=Number(input.value);g.thermal.cell_parameters??={};for(const cell of g.cells){g.thermal.cell_parameters[cell.id]??={};g.thermal.cell_parameters[cell.id][key]=Number(input.value);}}}
 S.history.push(snapshot());S.settings=draft;S.graph=g;S.dirty=true;S.testError=null;S.running=true;render();
 try{await persist();if(S.doc?.id!==designId||contextEpoch!==epoch)return;const test=await api('run',{design_id:designId,version:S.doc.version});if(tour.state.active&&designId===tour.state.exampleId){tour.mark('baselineId',test.id);tour.mark('probed',false);}if(S.doc?.id!==designId||contextEpoch!==epoch){notify('The test finished and is saved with its original design.');return;}const doc=await api('open',{design_id:designId});if(contextEpoch!==epoch)return;S.doc=doc;S.test=test;S.index=test.rows.length-1;S.view='results';S.hidden.clear();await refreshCatalog();}
 catch(e){if(S.doc?.id===designId&&contextEpoch===epoch)S.testError=e.message;else notify(e.message,true);}
 finally{S.running=false;render();}
}
async function ask(message){
 message=message?.trim();if(!message||S.chatBusy)return;
 const epoch=contextEpoch,designId=S.doc?.id||null,comparisonIds=S.view==='compare'?S.comparison?.tests.map(t=>t.id):null,selectedAtRequest=S.selected,testAtRequest=['results','limits'].includes(S.view)?S.test?.id||null:null,investigationAtRequest=S.view==='limits'?S.investigation?.id||null:null;
 S.ai=true;S.chatError=null;chatDraft='';S.messages.push({role:'user',content:message});S.chatBusy=true;render();
 try{await persist();if(contextEpoch!==epoch)return;const response=await api('chat',{messages:S.messages.slice(-15).map(m=>({role:m.role,content:m.content})),design_id:designId,selected:selectedAtRequest,test_id:testAtRequest,comparison_ids:comparisonIds,investigation_id:investigationAtRequest});if(contextEpoch!==epoch){notify('The AI response belonged to the previous design. Ask again here to use this design.');return;}S.messages.push({role:'assistant',content:response.message,proposal:response.proposal});if(!designId&&response.proposal?.new_design&&response.proposal.cell_count>0){const conversation=S.messages;try{const draft=await api('apply_proposal',{proposal_id:response.proposal.id});if(contextEpoch!==epoch){notify('Your new AI draft is saved in My designs.');return;}response.proposal.applied=true;response.proposal.created=true;loadDoc(draft);S.messages=conversation;S.ai=true;await refreshCatalog();notify('Your editable draft is ready on the canvas.');}catch(e){if(contextEpoch===epoch)S.chatError='The draft could not open automatically. '+e.message;}}if(tour.state.active&&comparisonIds?.includes(tour.state.baselineId)&&comparisonIds?.includes(tour.state.alternativeId))tour.mark('aiAnswered');}
 catch(e){if(contextEpoch===epoch)S.chatError=e.message;else notify(e.message,true);}
 finally{S.chatBusy=false;render();document.querySelector('#chat-input')?.focus();}
}
async function goView(view){await persist();contextEpoch++;const epoch=contextEpoch;S.view=view;S.selected=null;S.pending=null;S.testError=null;if(view==='results'&&!S.test&&S.doc.history.length){const test=await api('test',{test_id:S.doc.history.find(t=>t.current)?.id||S.doc.history[0].id});if(contextEpoch!==epoch)return;S.test=test;S.index=S.test.rows.length-1;}render();}
async function comparePage(){await persist();const epoch=++contextEpoch;await refreshCatalog();const docs=await Promise.all(S.catalog.designs.filter(d=>d.tests).map(d=>api('open',{design_id:d.id})));if(contextEpoch!==epoch)return;S.allTests=docs.flatMap(d=>d.history).sort((a,b)=>b.created_utc.localeCompare(a.created_utc));S.compareLeft=S.comparison?.tests[0].id||(S.allTests.some(t=>t.id===S.compareLeft)?S.compareLeft:S.test?.id)||S.allTests[0]?.id;S.compareRight=S.comparison?.tests[1].id||(S.allTests.some(t=>t.id===S.compareRight)&&S.compareRight!==S.compareLeft?S.compareRight:S.allTests.find(t=>t.id!==S.compareLeft)?.id);S.view='compare';render();}
function selectedConductor(){const wire=S.graph.connections.find(w=>w.id===S.selected);if(wire)return wire;const output=Object.keys(S.graph.output).find(p=>S.graph.output[p]===S.selected);return output?{output,conductor:S.graph.output_leads?.[output]}:null;}
async function action(action){
 if(action.startsWith('tour:')){await tourAction(action.slice(5));return;}
 if(action==='conductor:apply'){const wire=selectedConductor(),root=document.querySelector('#conductor-editor');if(!wire||![...root.querySelectorAll('input,textarea')].every(el=>el.reportValidity()))return;const definition=readConductor(wire,S.catalog.conductor_reference,root),v=conductorValues(definition);mutate(()=>{if(wire.output){S.graph.output_leads??={};S.graph.output_leads[wire.output]=definition;return;}wire.conductor=definition;wire.resistance_mohm=v.resistance_mohm;wire.source='Calculated from rectangular-conductor dimensions and total end-contact resistance; full sources saved with this connection.';});await persist();notify('Connection resistance now follows the saved dimensions.');return;}
 if(action==='conductor:direct'){const wire=selectedConductor();mutate(()=>{if(wire.output){delete S.graph.output_leads[wire.output];if(!Object.keys(S.graph.output_leads).length)delete S.graph.output_leads;return;}delete wire.conductor;wire.source='Direct resistance assumption; physical conductor dimensions no longer specified.';});return;}
 if(action==='home'){await persist();contextEpoch++;S.doc=null;S.graph=null;S.selected=null;S.test=null;S.ai=false;S.messages=[];S.chatError=null;await refreshCatalog();render();}
 else if(action==='example')await createExample();
 else if(action==='new')newDialog();
 else if(action==='close-dialog')dialog.close();
 else if(action==='custom-cell')showDialog('Add your own cell',customCellForm());
 else if(action.startsWith('custom-version:'))showDialog('Create a new cell version',customCellForm(S.catalog.library.find(m=>m.key===action.slice(15))));
 else if(action==='ask-comparison'){S.ai=true;chatDraft=comparisonQuestion;render();document.querySelector('#chat-input')?.focus();}
 else if(action==='designs'){await persist();await refreshCatalog();showDialog('Your battery designs',`<div class="design-list">${S.catalog.designs.map(designRow).join('')}</div><div class="dialog-footer">${btn('new','New design','plus','primary')}</div>`);}
 else if(action.startsWith('open:'))await openDesign(action.slice(5));
 else if(action.startsWith('view:'))await goView(action.slice(5));
 else if(action==='ai'){S.ai=!S.ai;render();if(S.ai)document.querySelector('#chat-input')?.focus();}
 else if(action==='close-ai'){S.ai=false;render();}
 else if(action==='close-panel'){S.selected=null;render();}
 else if(action.startsWith('mode:')){S.mode=action.slice(5);render();}
 else if(action.startsWith('tool:')){S.tool=action.slice(5);S.pending=null;S.selected=null;render();}
 else if(action==='dismiss-guide'){S.onboarding=false;render();}
 else if(action.startsWith('setup-type:')){setup.test_type=action.slice(11);setup.preset=loadChoices[setup.test_type][0][0];Object.assign(setup,presetValues[setup.preset]||{});setupDialog();}
 else if(action.startsWith('setup-load:')){readSetup();setup.preset=action.slice(11);Object.assign(setup,presetValues[setup.preset]||{});setupDialog();}
 else if(action==='setup-next'){const form=dialog.querySelector('#setup-load-form');if(form&&!form.reportValidity())return;readSetup();setup.step++;setupDialog();}
 else if(action==='setup-back'){readSetup();setup.step--;setupDialog();}
 else if(action==='cooling-low'){const field=document.querySelector('#cooling-conductance');if(field){field.value='0.0764';field.dataset.edited='true';}}
 else if(action==='smallest'){await openLimits();const condition=document.querySelector('#limit-condition');if(condition)condition.value='cell_count';await runLimitSearch();}
 else if(action==='help')showDialog('Your first experiment',`<div class="tutorial-step">${icon('pointer')}<div><h3>Build your circuit</h3><p>Add a cell, click it to edit its starting charge, and drag to arrange it. Choose Connect, then click the two terminals you want to join.</p></div></div><div class="tutorial-step">${icon('wire')}<div><h3>Choose the outputs</h3><p>Select a terminal, then choose Use as output. Set one positive and one negative output to connect the load.</p></div></div><div class="tutorial-step">${icon('play')}<div><h3>Choose a test</h3><p>Open Test. Set the current, duration in minutes and room temperature, then run it.</p></div></div><div class="tutorial-step">${icon('chart')}<div><h3>Explore what changed</h3><p>Hover over a graph to inspect values. Click to pin a moment, or use the time slider. Try a what-if to test a single change.</p></div></div><div class="tutorial-step">${icon('spark')}<div><h3>Ask the copilot</h3><p>Ask for an explanation or a different design. The AI shows proposed edits before you apply them.</p></div></div><div class="shortcut-help"><span><kbd class="key">⌘ Z</kbd> Undo</span><span><kbd class="key">Delete</kbd> Remove selection</span><span><kbd class="key">Esc</kbd> Cancel connection</span></div><div class="dialog-footer">${btn('tour:start','Try the guided example','play','primary')}${btn('close-dialog','Close',null,'quiet')}</div>`);
 else if(action==='library')libraryDialog();
 else if(action.startsWith('add:')){let id;mutate(()=>{id=addCell(S.graph,action.slice(4));S.selected=id;S.ai=false;});dialog.close();notify('Cell added. Connect its terminals to include it in the circuit.');}
 else if(action==='delete'){if(!S.selected)return;const name=S.graph.cells.find(c=>c.id===S.selected)?.name||'Connection';mutate(()=>{removePart(S.graph,S.selected);S.selected=null;S.pending=null;});notify(name+' removed. Use Undo to restore it.');}
 else if(action==='undo'||action==='redo'){const previous=action==='undo'?S.history.back(snapshot()):S.history.forward(snapshot());if(previous){S.graph=previous.graph;S.settings=previous.settings;S.selected=null;dirty();render();}}
 else if(action==='connect-from'){S.pending=S.selected;S.tool='connect';S.selected=null;render();}
 else if(action.startsWith('output:')){mutate(()=>{S.graph.output[action.slice(7)]=S.selected;});notify('Battery output updated.');}
 else if(action==='rename')showDialog('Name this design',`<form id="rename-form"><label for="rename-input">Design name</label><input id="rename-input" name="name" value="${esc(S.graph.name)}" maxlength="100" required><div class="dialog-footer">${btn('duplicate','Save a copy','copy')}<button type="submit" class="primary">Save name</button></div></form>`);
 else if(action==='duplicate'){await persist();const name=dialog.querySelector('[name=name]')?.value||S.graph.name+' copy';const doc=await api('create',{copy_id:S.doc.id,name});loadDoc(doc);dialog.close();render();notify('A separate copy is ready to edit.');}
 else if(action.startsWith('template:')){templateChoice=action.slice(9);dialog.querySelector('.template-options').innerHTML=templateOptions();const count=dialog.querySelector('#new-count');count.disabled=templateChoice==='blank';count.closest('.field').hidden=templateChoice==='blank';}
 else if(action.startsWith('suggest:'))await ask(action.slice(8));
 else if(action==='ask-selected')await ask('Explain '+(S.graph.cells.find(c=>c.id===S.selected)?.name||'this selected connection')+' and what I can change.');
 else if(action==='ask-results')await ask('Explain the most important finding in this test and suggest one useful design experiment.');
 else if(action.startsWith('apply:')){await persist();const epoch=contextEpoch;const response=await api('apply_proposal',{proposal_id:action.slice(6)});if(contextEpoch!==epoch){notify('The approved edit was saved with its original design.');return;}const messages=S.messages;for(const m of messages)if(m.proposal?.id===action.slice(6))m.proposal.applied=true;loadDoc(response);S.messages=messages;S.ai=true;render();notify('Proposed changes applied. Test the new design to see the result.');}
 else if(action.startsWith('metric:')){S.metric=action.slice(7);S.hidden.clear();chartPinned=false;render();}
 else if(action.startsWith('legend:')){const i=Number(action.slice(7));if(S.hidden.has(i))S.hidden.delete(i);else if(S.hidden.size<S.test.graph.cells.length-1)S.hidden.add(i);render();}
 else if(action==='show-assembly'){S.showAssembly=!S.showAssembly;render();if(S.showAssembly)document.querySelector('#results-assembly')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
 else if(action==='edit-selected'){S.view='build';if(!S.graph.cells.some(c=>c.id===S.selected))S.selected=null;render();}
 else if(action==='whatif'){await persist();S.selected=null;S.view='whatif';render();}
 else if(action.startsWith('scenario:'))await runScenario(action.slice(9));
 else if(action==='compare')await comparePage();
 else if(action==='limits')await openLimits();
 else if(action==='limit-stop'){S.screenCancel=true;render();}
 else if(action==='limit-resume')await runLimitSearch(true);
 else if(action.startsWith('limit-select:')){S.screenSelected=Number(action.slice(13));render();}
 else if(action.startsWith('limit-open:'))await openLimitCase(Number(action.slice(11)));
 else if(action==='ask-limits')await ask('Explain the first limit found in this investigation and suggest one design change to test. Distinguish a model coverage boundary from a component operating limit or a design target.');
 else if(action==='export'&&S.test)await exportTest();
 else if(action==='model')modelDialog();
 else if(action==='verification')verificationDialog();
 else if(action==='add-interval'){captureIntervals();const end=S.settings.profile.at(-1).end_s;S.settings.profile.push({start_s:end,end_s:end+60,current_A:0});dirty();render();document.querySelectorAll('#test-form details')[0].open=true;}
 else if(action.startsWith('remove-interval:')){captureIntervals();const i=Number(action.slice(16));if(S.settings.profile.length>1){S.settings.profile.splice(i,1);let t=0;S.settings.profile=S.settings.profile.map(p=>{const dur=p.end_s-p.start_s;const x={...p,start_s:t,end_s:t+dur};t+=dur;return x;});dirty();render();document.querySelectorAll('#test-form details')[0].open=true;}}
 else if(action==='thermal-contacts')thermalContactsDialog();
}
function modelDialog(){const keys=[...new Set(S.graph.cells.map(c=>c.model))];const used=keys.map(key=>S.catalog.library.find(m=>m.key===key)).filter(Boolean);showDialog('The model behind your design',`<div class="about-model"><h3>Electrical behaviour</h3><p>The solver calculates currents and voltages from your actual connections. Temperature-dependent cell models update their electrical properties as the cells warm or cool.</p><h3>Cells in this design</h3>${used.map(m=>`<p><strong>${esc(m.name)}</strong> · ${fmt(m.capacity_Ah,2)} Ah<br>${esc(m.status||'Original fit')}<br>${m.basic?'Constant parameters at the chosen starting temperature; no measured temperature response.':'Cell-temperature coordinates: '+fmt(m.temperature_range_C?.[0],1)+' to '+fmt(m.temperature_range_C?.[1],1)+' °C.'} ${m.source_url?`<a href="${esc(m.source_url)}" target="_blank" rel="noopener">Source</a>`:'Source: your own parameters.'}</p>`).join('')}<h3>Heat and cooling</h3><p>Electrical losses, declared heat capacity, cooling and thermal contacts determine the surface-equivalent cell temperature. Room temperature is a separate boundary condition. Model limits apply to the cell itself.</p><h3>What a result means</h3><p>A result is an estimate for the saved model, design and test conditions. Independent module and fixture validation remains necessary before relying on predictions for hardware.</p></div>`);}
function verificationDialog(){if(!S.test)return;const v=S.test.summary.verification;showDialog('Calculation checks',`<p>These checks catch solver and accounting mistakes. They do not measure agreement with a real battery.</p><dl><div><dt>Current conservation residual</dt><dd>${v.max_kcl_A.toExponential(2)} A</dd></div><div><dt>Voltage equation residual</dt><dd>${v.max_kvl_V.toExponential(2)} V</dd></div><div><dt>Instantaneous power balance</dt><dd>${v.max_power_residual_W.toExponential(2)} W</dd></div><div><dt>Cell charge accounting</dt><dd>${v.max_cell_charge_residual_As.toExponential(2)} A·s</dd></div><div><dt>Electrical energy balance</dt><dd>${v.final_energy_residual_Wh.toExponential(2)} Wh</dd></div><div><dt>Cell heat accounting</dt><dd>${v.max_thermal_residual_J===null?'Not modeled':v.max_thermal_residual_J.toExponential(2)+' J'}</dd></div><div><dt>First-law balance</dt><dd>${v.first_law_residual_J==null?'Not modeled':`${v.first_law_residual_J.toExponential(2)} J of ${v.electrical_dissipation_J.toFixed(0)} J electrical loss · ${v.first_law_closed?'closed':'not closed'}`}</dd></div></dl><p class="helper">Time integration has a finite step. Compare progressively smaller steps when studying a new load or topology.</p>`);}
function thermalContactsDialog(){showDialog('Heat transfer between cells',`<p>Add a contact only where your physical design provides a heat path. The value is heat transferred per degree of temperature difference.</p><form id="contacts-form"><div id="contact-rows">${S.graph.thermal.contacts.map((c,i)=>contactRow(c,i)).join('')}</div>${btn('add-contact','Add thermal contact','plus','text-button')}<div class="dialog-footer"><button type="submit" class="primary">Save contacts</button></div></form>`);}
function contactRow(c,i){const opts=selected=>S.graph.cells.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('');return `<div class="field contact-row"><label>Contact ${i+1}</label><div class="field-row"><select aria-label="First cell">${opts(c.a)}</select><select aria-label="Second cell">${opts(c.b)}</select></div><div class="field-row"><div class="field"><label>Conductance (W/°C)</label><input type="number" min="0" max="100" step="any" value="${c.conductance_W_K}" required></div>${btn('remove-contact:'+i,'Remove','trash','quiet')}</div></div>`;}
function captureIntervals(){const rows=[...document.querySelectorAll('[data-interval]')];if(!rows.length)return;let t=0;S.settings.profile=rows.map(row=>{const d=Number(row.querySelector('.interval-duration').value)*60;const p={start_s:t,end_s:t+d,current_A:Number(row.querySelector('.interval-current').value)};t+=d;return p;});}
function profileSummary(profile){return `<div class="profile-summary" aria-label="Actual test load"><h3>${profile.length===1?'Test load':'Load intervals'}</h3>${profile.map((p,i)=>`<p>${profile.length>1?(i+1)+'. ':''}${p.current_A===0?'Rest':Math.abs(p.current_A)+' A '+(p.current_A<0?'charging':'discharging')} for ${timeLabel(p.end_s-p.start_s)}</p>`).join('')}</div>`;}
function failurePage(){if(!S.test)return `<main id="main" class="page-wrap"><div class="page-intro"><h1>Where does this design break?</h1><p>Run a baseline test first. Then challenge the saved design with harder conditions.</p></div>${btn('view:test','Set up the baseline','play','primary')}</main>`;
 const inv=S.investigation,cases=inv?.cases||[],first=cases.find(c=>['design_target','component_limit','model_boundary','unsupported','protection'].includes(c.outcome.kind)),selected=cases[S.screenSelected]||first||cases[0];
 return `<main id="main" class="page-wrap"><div class="page-intro">${btn('view:results','Back to results','back','text-button')}<h1>Where does this design break?</h1><p>Challenge your saved design. See which cell reaches a limit, under which conditions and when.</p></div><form id="limits-form" class="limits-form"><div class="field"><label for="limit-condition">What should we make harder?</label><select id="limit-condition" name="condition" ${S.screenBusy?'disabled':''}><option value="load" ${inv?.condition==='load'?'selected':''}>Higher battery demand</option><option value="temperature" ${inv?.condition==='temperature'?'selected':''}>A warmer room</option><option value="connection" ${inv?.condition==='connection'?'selected':''}>A poorer electrical connection</option><option value="cell_count" ${inv?.condition==='cell_count'?'selected':''}>Find the smallest design</option></select></div><button type="submit" class="primary" ${S.screenBusy?'disabled':''}>${icon('play')}Find limits</button>${S.screenBusy?btn('limit-stop',S.screenCancel?'Stopping after this case…':'Stop after this case',null,'quiet',S.screenCancel):inv&&!inv.complete?btn('limit-resume','Resume saved tests',null):''}</form><p class="helper">Baseline: ${esc(S.test.design_name)} · ${esc(S.test.name)}. Each case uses the same saved cells, preparation and model versions.</p>${inv?`<div class="limits-progress" role="status">${S.screenBusy?'<span class="loading-mark"></span>':''}${cases.length} of ${inv.planned.length} cases calculated${inv.complete?' · Investigation complete':S.screenBusy?' · '+(S.screenCancel?'Stopping after the current calculation':'Testing '+esc(inv.planned[cases.length]?.name||'case')):' · Saved; ready to resume'}</div>${inv.condition==='cell_count'?sizingTable(inv,S.screenBusy,(i,busy)=>btn('limit-open:'+i,'Open','arrow','quiet',busy)):`${first?`<div class="limit-finding"><h2>${esc(first.outcome.label)}</h2><p><strong>${esc(first.name)}</strong>: ${esc(first.outcome.message)}</p></div>`:cases.length?`<p class="limits-observation">${inv.complete?'No limit was found in these cases.':'No limit found in the completed cases yet.'}</p>`:''}${selected?failurePreview(selected):''}${cases.length?`<div class="limits-table-wrap"><table class="limits-table"><thead><tr><th>Condition</th><th>Finding</th><th>First observed limit</th><th></th></tr></thead><tbody>${cases.map((c,i)=>`<tr class="${selected?.index===i?'selected':''}"><td><button type="button" class="text-button" data-act="limit-select:${i}">${esc(c.name)}</button></td><td><span class="limit-status ${['design_target','component_limit','protection'].includes(c.outcome.kind)?'hit':c.outcome.kind==='model_boundary'||c.outcome.kind==='unsupported'?'boundary':''}">${esc(c.outcome.label)}</span></td><td>${c.outcome.first_limit?c.outcome.first_limit.time_s===0?'At the start':timeLabel(c.outcome.first_limit.time_s):'None observed'}</td><td>${btn('limit-open:'+i,'Open case','arrow','quiet',S.screenBusy)}</td></tr>`).join('')}</tbody></table></div>`:''}`}<p class="helper limits-scope">${esc(inv.scope)} A calculated temperature may use assumed heat properties. The highlighted case is evidence for the recorded conditions, not a hardware safety rating.</p>`:''}<div class="results-next">${btn('ask-limits','Explain the findings with AI','spark','',!cases.length)}${btn('whatif','Try a specific design change','wire')}${btn('view:test','Edit my design targets','edit','text-button')}</div></main>`;
}
function failurePreview(c){const kind=c.outcome.kind,unit=c.outcome.first_limit?.metric,layer=unit==='temperature_C'||c.stop?.reason==='temperature_domain'?'temperature':'current',cells=c.graph.cells.filter(cell=>c.outcome.affected_cells.includes(cell.id)).map(cell=>cell.name),links=c.outcome.first_limit?(c.affected_connections||[]):[];return `<section class="failure-detail" aria-label="Selected investigation case"><div class="failure-preview">${renderCanvas(c.graph,{row:c.sample_row,layer,prefix:'failure',alertCells:c.outcome.affected_cells,alertConnections:links,interactive:false})}</div><div><h2>${esc(c.name)}</h2><p class="limit-status ${['design_target','component_limit','protection'].includes(kind)?'hit':''}">${esc(c.outcome.label)}</p><p>${esc(c.outcome.message)}</p>${c.outcome.first_limit?.current_A!==undefined?`<p class="helper">Calculated cell current at the start: <strong>${fmt(Math.abs(c.outcome.first_limit.current_A),2)} A</strong> at ${fmt(c.outcome.first_limit.temperature_C)} °C.</p>`:''}${cells.length?`<p class="helper">Highlighted: ${cells.map(esc).join(', ')}.</p>`:links.length?'<p class="helper">The highlighted connection is the pressure-test change.</p>':''}${c.outcome.first_limit?`<p class="helper">${c.outcome.first_limit.time_s===0?'The conditions at the start already exceed the checked limit.':'First observed at '+timeLabel(c.outcome.first_limit.time_s)+'.'}</p>`:''}${c.status==='stopped'?'<p class="helper">This test stopped early. The remaining mission was not calculated.</p>':''}${btn('limit-open:'+c.index,'Open this as a design','arrow','text-button',S.screenBusy)}</div></section>`;}
async function openLimits(){await persist();const epoch=++contextEpoch;if(!S.test&&S.doc.history.length){const test=await api('test',{test_id:S.doc.history.find(t=>t.current)?.id||S.doc.history[0].id});if(contextEpoch!==epoch)return;S.test=test;S.index=test.rows.length-1;}S.view='limits';S.selected=null;S.ai=false;if(S.investigation?.baseline_test_id!==S.test?.id){S.investigation=null;S.screenSelected=0;await refreshCatalog();const recent=S.catalog.investigations?.filter(i=>i.baseline_test_id===S.test?.id).at(-1);if(recent){const saved=await api('investigation',{investigation_id:recent.id});if(contextEpoch!==epoch)return;S.investigation=saved;}}render();}
async function runLimitSearch(resume=false){if(S.screenBusy)return;await persist();if(!S.test)throw new Error('Run a baseline test first.');const epoch=contextEpoch,designId=S.doc.id,baselineId=S.test.id,condition=document.querySelector('#limit-condition')?.value||'load';S.screenBusy=true;S.screenCancel=false;render();try{let inv=resume?S.investigation:await api('begin_investigation',{design_id:designId,version:S.doc.version,baseline_test_id:baselineId,condition});if(contextEpoch!==epoch)return;S.investigation=inv;S.screenSelected=0;render();for(let i=inv.cases.length;i<inv.planned.length;i++){if(S.screenCancel||contextEpoch!==epoch)break;inv=await api('investigate_case',{investigation_id:inv.id,case_index:i});if(contextEpoch!==epoch)break;S.investigation=inv;const first=inv.cases.findIndex(c=>['design_target','component_limit','model_boundary','unsupported','protection'].includes(c.outcome.kind));if(first>=0)S.screenSelected=first;render();}await refreshCatalog();}finally{S.screenBusy=false;if(contextEpoch===epoch)render();}}
async function openLimitCase(index){const id=S.investigation?.id;if(!id)return;await persist();const epoch=contextEpoch;S.running=true;try{const r=await api('open_investigation_case',{investigation_id:id,case_index:index});if(contextEpoch!==epoch){notify('The investigation case is saved in My designs.');return;}loadDoc(r.design);S.selected=r.outcome.affected_cells[0]||null;if(r.test){S.test=r.test;S.index=r.test.rows.length-1;S.view='results';S.compareLeft=r.baseline_test_id;S.compareRight=r.test.id;}else S.ai=false;await refreshCatalog();render();}finally{S.running=false;}}
function libraryDialog(){const main=S.catalog.library.filter(m=>!m.legacy),older=S.catalog.library.filter(m=>m.legacy);const row=m=>`<div class="library-item">${thumbnail({name:m.name,model:m.key})}<div><h3>${esc(m.name)}</h3><p>${fmt(m.capacity_Ah,2)} Ah${m.custom?' · your cell':''}</p><p>${esc(modelDescription(m))}</p></div>${btn('add:'+m.key,'Add cell','plus','primary',!S.graph||S.graph.cells.length>=16)}</div>`;showDialog('Add a battery cell',`<p>Choose a cell, then connect its terminals on the canvas.</p>${main.map(row).join('')}<div class="library-custom">${btn('custom-cell','Add your own cell','plus','text-button')}<p class="helper">Enter basic properties, import a measured curve or supply your own model.</p></div>${older.length?`<details><summary>Original measured samples</summary><p>Keep these for earlier studies and comparisons.</p>${older.map(row).join('')}</details>`:''}`);}
async function saveCustomCell(form){const button=form.querySelector('[type=submit]'),error=form.querySelector('#custom-cell-error');button.disabled=true;error.className='';error.textContent='';try{const args=await readCustomCell(form);const model=await api('create_cell',args);await refreshCatalog();dialog.close();if(tour.state.active&&tour.state.step===6)tour.dismiss();if(S.doc)libraryDialog();else showDialog('Your cell is saved',`<p>${esc(model.name)} is available when you add a cell to a design.</p><div class="dialog-footer">${btn('new','Create a design','plus','primary')}${btn('close-dialog','Done',null,'quiet')}</div>`);notify('Custom cell saved. Existing designs keep their original models.');render();}catch(e){error.className='error-inline';error.textContent=e.message;}finally{button.disabled=false;}}
function friendlyChange(d,tests=[]){const cells=tests.flatMap(t=>t.graph?.cells||[]),cellName=id=>cells.find(c=>c.id===id)?.name||'Cell';let path=d.path.replace(/^design\./,'');for(const test of tests)for(const wire of test.graph?.connections||[])path=path.replace('connections.'+wire.id+'.','Connection '+describeConnection(test.graph,wire)+'.');for(const c of cells)path=path.replaceAll(c.id,c.name);const labels={'output_leads.negative':'Negative external connector route','output_leads.positive':'Positive external connector route','length_mm':'path length (mm)','width_mm':'width (mm)','thickness_mm':'thickness (mm)','contact_mohm':'total end-contact resistance (mΩ)','reference_temperature_C':'material reference temperature (°C)','resistivity_ohm_m':'material resistivity (Ω·m)','density_kg_m3':'material density (kg/m³)','conductor':'metal link','output.negative':'Negative battery output','output.positive':'Positive battery output','temperature_C':'temperature (°C)','charge_pct':'starting charge (%)','resistance_mohm':'resistance (mΩ)','ambient_C':'room temperature (°C)','heat_capacity_J_K':'heat capacity (J/°C)','ambient_conductance_W_K':'cooling (W/°C)','current_A':'current (A)','end_s':'end time (s)','start_s':'start time (s)','polarization_V':'initial relaxation (V)'};for(const [key,label] of Object.entries(labels))path=path.replace(key,label);path=path.replace(/^cells\./,'').replace(/^connections\./,'Connection ').replaceAll('.',' · ').replaceAll('_',' ');const value=v=>{if(typeof v==='number')return String(Number(v.toPrecision(5)));if(v===null)return 'unset';if(typeof v==='object')return 'updated';if(typeof v==='string'&&/^cell\d+:[pn]$/.test(v)){const [id,pole]=v.split(':');return cellName(id)+(pole==='p'?' positive':' negative');}return String(v);};return path+': '+value(d.before)+' → '+value(d.after);}
async function runScenario(scenario,showComparison=false){await persist();const epoch=contextEpoch,designId=S.doc.id,version=S.doc.version,previous=S.test;if(!previous||previous.design_id!==designId)throw new Error('Run a baseline test for this design first.');S.running=true;render();try{const r=await api('investigate',{design_id:designId,version,scenario,baseline_test_id:previous.id});if(contextEpoch!==epoch){notify('The what-if test was saved as a separate design.');return;}const doc=await api('open',{design_id:r.design.id});if(contextEpoch!==epoch)return;loadDoc(doc);S.test=r.test;S.view='results';S.index=r.test.rows.length-1;S.compareLeft=previous.id;S.compareRight=r.test.id;if(showComparison){tour.mark('alternativeId',r.test.id);S.comparison=await api('compare',{test_ids:[previous.id,r.test.id]});await comparePage();}await refreshCatalog();notify('The changed design is tested. Your baseline is saved separately.');}finally{S.running=false;render();}}
async function exportTest(){const id=S.test.id,r=await workspaceFetch('/api/studio/export/'+encodeURIComponent(id));if(!r.ok)throw new Error('The report could not be generated. Keep this saved test and try Export again.');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='volt-forge-experiment.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);if(tour.state.active)tour.mark('exported');notify('Report and reproducible experiment ready.');render();}
function tourContext(){return {designId:S.doc?.id,rendered:!!S.graph?.cells.length,selectedCell:S.graph?.cells.some(c=>c.id===S.selected),inspector:S.view==='build'&&!S.ai&&!!S.selected,comparedIds:S.comparison?.tests.map(t=>t.id),sameConditions:S.comparison?.identical_test_conditions&&S.comparison?.model_versions_match&&S.comparison?.solver_versions_match};}
function tourElement(){const holder=document.createElement('div');holder.innerHTML=tourHtml();return holder.firstElementChild;}
function tourHtml(){if(!tour.state.active)return '';const step=tourSteps[tour.state.step],ready=tour.complete(tourContext()),away=tour.state.step<3&&S.doc?.id!==tour.state.exampleId;let cta='';
 if(!S.doc&&tour.state.step>=3)cta=btn('tour:resume','Resume guided experiment','play','primary');
 else if(away)cta=btn('tour:reopen','Reopen guided example','folder');
 else if(tour.state.step===1&&!ready)cta=btn('tour:select','Select Cell 1','pointer');
 else if(tour.state.step===2&&!ready)cta=btn(S.view==='test'?'tour:review':'view:test',S.view==='test'?'Use these test conditions':'Open Test','play','primary');
 else if(tour.state.step===3&&!ready)cta=btn(!S.test?'tour:run':'tour:probe',!S.test?'Run the example':'Inspect the chart',!S.test?'play':'chart','primary',S.running)+(S.test?btn('tour:run','Rerun test',null,'quiet',S.running):'');
 else if(tour.state.step===4&&!ready)cta=btn('tour:preview','Preview connection change','wire','primary',S.running);
 else if(tour.state.step===5&&!ready)cta=btn('tour:copilot','Prepare my question','spark','primary');
 else if(tour.state.step===6)cta=btn('export','Export example','download','primary',!S.test)+btn('tour:new','Create a design','plus')+btn('tour:custom','Add a custom cell',null,'quiet')+(tour.state.returnId?btn('tour:return','Return to my design',null,'quiet'):'');
 return `<section id="walkthrough" class="walkthrough" aria-labelledby="walkthrough-title"><div class="walkthrough-progress" aria-label="Step ${tour.state.step+1} of ${tourSteps.length}">${tourSteps.map((s,i)=>`<span class="${i<=tour.state.step?'done':''}"></span>`).join('')}</div><div class="walkthrough-copy"><h2 id="walkthrough-title">${esc(step.title)} <span>${tour.state.step+1} of ${tourSteps.length}</span></h2><p>${esc(step.body)}</p></div><div class="walkthrough-actions">${cta}${tour.state.step?btn('tour:back','Back',null,'quiet'):''}${btn('tour:next',tour.state.step===6?'Finish':'Next','arrow',ready?'primary':'',!ready)}${btn('tour:skip','Skip step',null,'quiet')}${iconBtn('tour:dismiss','Close walkthrough','close')}</div></section>`;
}
async function tourAction(action){
 if(action==='start'){await persist();const returnId=S.doc?.id||null;const doc=await api('create',{kind:'parallel',count:4,name:'Guided battery experiment'});tour.start(doc.id,returnId);loadDoc(doc);S.ai=false;dialog.close();await refreshCatalog();render();document.querySelector('#walkthrough [data-act="tour:next"]')?.focus();}
 else if(action==='dismiss'){tour.dismiss();render();}
 else if(action==='back'){tour.back();render();}
 else if(action==='next'||action==='skip'){tour.next(tourContext(),action==='skip');render();document.querySelector('#walkthrough button:not(:disabled)')?.focus();}
 else if(action==='reopen'){await openDesign(tour.state.exampleId);}
 else if(action==='resume'){const id=tour.state.alternativeId||tour.state.baselineId;if(id){const test=await api('test',{test_id:id});await openDesign(test.design_id);S.test=test;S.index=test.rows.length-1;S.view='results';if(tour.state.step>=4&&tour.state.alternativeId){S.comparison=await api('compare',{test_ids:[tour.state.baselineId,tour.state.alternativeId]});await comparePage();}render();}else await openDesign(tour.state.exampleId);}
 else if(action==='select'){if(S.doc?.id!==tour.state.exampleId)await openDesign(tour.state.exampleId);S.view='build';S.selected=S.graph.cells[0]?.id;S.ai=false;render();document.querySelector('#cell-charge')?.focus();}
 else if(action==='review'){const form=document.querySelector('#test-form');if(!form?.reportValidity())return;await persist();tour.mark('reviewed');tour.next(tourContext());render();}
 else if(action==='run'){if(S.doc?.id!==tour.state.exampleId)await openDesign(tour.state.exampleId);await goView('test');await runTest();}
 else if(action==='probe'){await goView('results');document.querySelector('#result-time')?.focus();}
 else if(action==='preview'){if(!tour.state.baselineId)throw new Error('Run the guided example first, or skip this step.');const test=await api('test',{test_id:tour.state.baselineId});showDialog('Preview one connection change',`<p>The negative battery output moves from ${esc(test.graph.cells.find(c=>c.id===test.graph.output.negative.split(':')[0])?.name)} to ${esc(test.graph.cells.at(-1).name)}. The cells, other connections and test conditions stay the same.</p><p class="helper">A separate design will be created and tested from this saved baseline.</p><div class="dialog-footer">${btn('close-dialog','Cancel',null,'quiet')}${btn('tour:apply','Create copy and test','play','primary')}</div>`);}
 else if(action==='apply'){dialog.close();const test=await api('test',{test_id:tour.state.baselineId});if(S.doc?.id!==test.design_id)await openDesign(test.design_id);S.test=test;await runScenario('takeoff',true);}
 else if(action==='copilot'){if(!S.doc){await openDesign(tour.state.exampleId);}if(tour.state.baselineId&&tour.state.alternativeId){S.comparison=await api('compare',{test_ids:[tour.state.baselineId,tour.state.alternativeId]});await comparePage();}S.ai=true;chatDraft=comparisonQuestion;render();document.querySelector('#chat-input')?.focus();}
 else if(action==='new'){tour.dismiss();render();newDialog();}
 else if(action==='custom'){tour.dismiss();render();showDialog('Add your own cell',customCellForm());}
 else if(action==='return'){const id=tour.state.returnId;tour.dismiss();if(id)await openDesign(id);else render();}
}
function bindCanvas(){
 const svg=document.querySelector('#battery-canvas');if(!svg||S.view!=='build')return;
 svg.addEventListener('pointerdown',e=>{
  const cellEl=e.target.closest('[data-cell]');if(!cellEl||e.target.closest('[data-terminal]')||S.tool==='connect'||e.button!==0)return;
  const id=cellEl.dataset.cell,c=S.graph.cells.find(c=>c.id===id),before=snapshot();
  e.preventDefault();svg.setPointerCapture(e.pointerId);
  const start={x:e.clientX,y:e.clientY,cx:c.x,cy:c.y},scale=svg.viewBox.baseVal.width/svg.getBoundingClientRect().width;let moved=false;
  let frame=0,latest=null;
  const paint=()=>{frame=0;if(!latest||!moved)return;
   c.x=Math.min(2800,Math.max(85,Math.round((start.cx+(latest.x-start.x)*scale)/10)*10));c.y=Math.min(2200,Math.max(130,Math.round((start.cy+(latest.y-start.y)*scale)/10)*10));
   cellEl.setAttribute('transform',`translate(${c.x} ${c.y})`);
   for(const terminal of svg.querySelectorAll(`[data-terminal^="${id}:"]`))terminal.setAttribute('transform',`translate(${c.x-start.cx} ${c.y-start.cy})`);
   for(const w of S.graph.connections){
    const node=svg.querySelector(`[data-wire="${w.id}"]`),geometry=wireGeometry(S.graph,w);
    for(const path of node.querySelectorAll('path'))path.setAttribute('d',geometry.path);
    node.querySelector('g')?.setAttribute('transform',`translate(${geometry.x} ${geometry.y})`);
   }
  };
  const move=event=>{if(Math.hypot(event.clientX-start.x,event.clientY-start.y)>4)moved=true;latest={x:event.clientX,y:event.clientY};if(moved&&!frame)frame=requestAnimationFrame(paint);};
  const up=()=>{if(frame)cancelAnimationFrame(frame);paint();window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up);if(moved){S.history.push(before);S.selected=id;dirty();render();}else{S.selected=id;S.ai=false;S.onboarding=false;render();}};
  window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true});window.addEventListener('pointercancel',up,{once:true});
 });
}
function bindChart(){const svg=document.querySelector('#result-chart');if(!svg||!S.test)return;let frame=0;
 const at=event=>{const rect=svg.getBoundingClientRect(),x=(event.clientX-rect.left)*Number(svg.dataset.total)/rect.width;const time=Math.max(0,Math.min(1,(x-Number(svg.dataset.left))/Number(svg.dataset.width)))*Number(svg.dataset.duration);return nearestIndex(S.test.rows,time);};
 svg.addEventListener('pointermove',e=>{if(chartPinned)return;const index=at(e),x=e.clientX;if(frame)cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{frame=0;if(svg.isConnected&&!chartPinned)probe(index,x);});});
 svg.addEventListener('pointerleave',()=>{if(frame)cancelAnimationFrame(frame);frame=0;if(!chartPinned)document.querySelector('#chart-tooltip')?.classList.remove('visible');});
 svg.addEventListener('click',e=>{S.index=at(e);chartPinned=!chartPinned;probe(S.index,e.clientX);});
}
function probe(index,clientX){S.index=Math.max(0,Math.min(S.test.rows.length-1,index));const svg=document.querySelector('#result-chart');if(!svg)return;svg.querySelector('#chart-probe').innerHTML=probeSvg(S.test,S.metric,S.index,S.hidden,Number(svg.dataset.min),Number(svg.dataset.max),Number(svg.dataset.duration));
 const tooltip=document.querySelector('#chart-tooltip');tooltip.innerHTML=pointValues(S.test,S.metric,S.index,S.hidden);if(clientX!==undefined){tooltip.classList.add('visible');const rect=document.querySelector('#chart-area').getBoundingClientRect();tooltip.style.left=Math.max(8,Math.min(rect.width-tooltip.offsetWidth-8,clientX-rect.left+18))+'px';}
 const slider=document.querySelector('#result-time');if(slider){slider.value=S.index;slider.setAttribute('aria-valuetext',timeLabel(S.test.rows[S.index].time_s));}const readout=document.querySelector('#time-readout');if(readout)readout.textContent=timeLabel(S.test.rows[S.index].time_s);
 const assembly=document.querySelector('#results-assembly');if(assembly)assembly.innerHTML=renderCanvas(S.test.graph,{mode:S.mode,selected:S.selected,layer:S.metric,row:S.test.rows[S.index],prefix:'results'});
 if(tour.state.active&&S.test.id===tour.state.baselineId&&!tour.state.probed){tour.mark('probed');document.querySelector('#walkthrough')?.replaceWith(tourElement());}
 if(S.selected&&!S.ai){const panel=document.querySelector('.side-panel');if(panel)panel.outerHTML=selectedPanel();}
}
app.addEventListener('click',async event=>{const button=event.target.closest('[data-act]');if(button){try{await action(button.dataset.act);}catch(e){notify(e.message,true);}return;}
 if(event.target.closest('.failure-preview'))return;
 const term=event.target.closest('[data-terminal]');if(term&&S.doc){if(S.view!=='build')return;const t=term.dataset.terminal;if(S.tool==='connect'){if(!S.pending){S.pending=t;render();}else{try{mutate(()=>{connect(S.graph,S.pending,t);S.pending=null;S.selected=null;});}catch(e){notify(e.message,true);}}}else{S.selected=t;S.ai=false;render();}return;}
 const wire=event.target.closest('[data-wire]');if(wire&&S.doc){S.selected=wire.dataset.wire;S.ai=false;render();return;}
 const cell=event.target.closest('[data-cell]');if(cell&&S.view==='results'){S.selected=cell.dataset.cell;S.ai=false;render();}
});
dialog.addEventListener('click',async event=>{const b=event.target.closest('[data-act]');if(!b)return;try{if(b.dataset.act==='add-contact'){const holder=dialog.querySelector('#contact-rows');holder.insertAdjacentHTML('beforeend',contactRow({a:S.graph.cells[0]?.id,b:S.graph.cells[1]?.id,conductance_W_K:.05},holder.children.length));}else if(b.dataset.act.startsWith('remove-contact:'))b.closest('.contact-row').remove();else await action(b.dataset.act);}catch(e){notify(e.message,true);}});
app.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;try{if(form.id==='home-chat')await ask(new FormData(form).get('prompt'));else if(form.id==='chat-form')await ask(new FormData(form).get('message'));else if(form.id==='test-form')await runTest();else if(form.id==='limits-form')await runLimitSearch();else if(form.id==='compare-form'){const epoch=contextEpoch,data=new FormData(form);S.compareLeft=data.get('left');S.compareRight=data.get('right');const result=await api('compare',{test_ids:[S.compareLeft,S.compareRight]});if(contextEpoch===epoch){S.comparison=result;render();}}}catch(e){notify(e.message,true);}});
dialog.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;try{if(form.id==='custom-cell-form'){await saveCustomCell(form);return;}if(form.id==='new-form'){await persist();const data=new FormData(form);const doc=await api('create',{kind:templateChoice,count:templateChoice==='blank'?0:Number(data.get('count')),name:data.get('name'),mission:missionRequest(setup)});loadDoc(doc);if(presetEdits(setup,S.settings)){S.dirty=true;await persist();}dialog.close();render();await refreshCatalog();}else if(form.id==='rename-form'){const name=new FormData(form).get('name').trim();if(!name)return;mutate(()=>S.graph.name=name);await persist();dialog.close();render();}else if(form.id==='contacts-form'){const contacts=[...form.querySelectorAll('.contact-row')].map(row=>{const selects=row.querySelectorAll('select');return {a:selects[0].value,b:selects[1].value,conductance_W_K:Number(row.querySelector('input').value)};});mutate(()=>S.graph.thermal.contacts=contacts);await persist();dialog.close();render();}}catch(e){notify(e.message,true);}});
app.addEventListener('input',event=>{if(event.target.id==='result-time')probe(Number(event.target.value));if(event.target.id==='cell-charge-range'){const input=document.querySelector('#cell-charge');if(input)input.value=event.target.value;}if(event.target.id==='chat-input')chatDraft=event.target.value;if(['heat-capacity','cooling-conductance'].includes(event.target.id))event.target.dataset.edited='true';if(event.target.matches('[data-conductor]')){const wire=selectedConductor();if(wire)updateConductorPreview(wire,S.catalog.conductor_reference);}});
app.addEventListener('change',async event=>{const el=event.target;try{if(el.dataset.cellField){if(!el.reportValidity())return;const cell=S.graph.cells.find(c=>c.id===S.selected),field=el.dataset.cellField;if(!cell)return;mutate(()=>cell[field]=['name','model'].includes(field)?el.value:Number(el.value));}
 else if(el.dataset.cellThermal){if(!el.reportValidity())return;mutate(()=>{const th=S.graph.thermal;th.cell_parameters??={};th.cell_parameters[S.selected]??={};th.cell_parameters[S.selected][el.dataset.cellThermal]=Number(el.value);});}
 else if(el.id==='cell-charge-range'){const cell=S.graph.cells.find(c=>c.id===S.selected);mutate(()=>cell.charge_pct=Number(el.value));}
 else if(el.dataset.wireField){if(!el.reportValidity())return;const wire=S.graph.connections.find(w=>w.id===S.selected);mutate(()=>wire[el.dataset.wireField]=el.dataset.wireField==='source'?el.value:Number(el.value));}
 else if(el.closest('#test-form')&&el.matches('input,select,textarea')){
  if(el.id==='protection-enabled'){S.settings.protection=el.checked?protectionDefaults():null;dirty();render();document.querySelector('#protection-settings').open=true;return;}
  if(el.classList.contains('protection-input')){if(!el.reportValidity())return;S.settings.protection=readProtection(el.closest('form'));dirty();return;}
  if(!el.reportValidity())return;
  if(el.matches('.interval-current,.interval-duration')){
   captureIntervals();const current=document.querySelector('#test-current'),direction=document.querySelector('#test-direction');
   document.querySelector('#test-duration').value=S.settings.profile.at(-1).end_s/60;
   if(S.settings.profile.length===1){current.value=Math.abs(S.settings.profile[0].current_A);direction.value=S.settings.profile[0].current_A<0?'charge':S.settings.profile[0].current_A===0?'rest':'discharge';}
  }else if(['test-current','test-duration','test-direction'].includes(el.id)&&S.settings.profile.length===1){
   const form=document.querySelector('#test-form'),data=new FormData(form),direction=data.get('direction');
   const current=direction==='rest'?0:Number(data.get('current'))*(direction==='charge'?-1:1);
   S.settings.profile=[{start_s:0,end_s:Number(data.get('duration'))*60,current_A:current}];
   form.querySelector('.interval-current').value=current;form.querySelector('.interval-duration').value=Number(data.get('duration'));
  }else if(el.id==='test-ambient')S.settings.ambient_C=Number(el.value);
  else if(el.id==='test-step')S.settings.dt_s=Number(el.value);
  else if(el.id==='heat-capacity'&&el.value!==''){S.graph.thermal.heat_capacity_J_K=Number(el.value);S.graph.thermal.cell_parameters??={};for(const cell of S.graph.cells){S.graph.thermal.cell_parameters[cell.id]??={};S.graph.thermal.cell_parameters[cell.id].heat_capacity_J_K=Number(el.value);}}
  else if(el.id==='cooling-conductance'&&el.value!==''){S.graph.thermal.ambient_conductance_W_K=Number(el.value);S.graph.thermal.cell_parameters??={};for(const cell of S.graph.cells){S.graph.thermal.cell_parameters[cell.id]??={};S.graph.thermal.cell_parameters[cell.id].ambient_conductance_W_K=Number(el.value);}}
  else{const target={'target-temperature':'temperature_C','target-current':'current_A','target-voltage':'min_voltage_V','target-imbalance':'imbalance_pct'}[el.id];if(target)S.settings.limits[target]=el.value===''?null:Number(el.value);}
  const loadSummary=document.querySelector('#test-form')?.parentElement?.querySelector('.profile-summary');if(loadSummary)loadSummary.outerHTML=profileSummary(S.settings.profile);
  dirty();
 }
 else if(el.id==='test-history'&&el.value){const epoch=++contextEpoch,test=await api('test',{test_id:el.value});if(contextEpoch!==epoch)return;S.test=test;S.index=S.test.rows.length-1;S.view='results';S.selected=null;S.hidden.clear();render();}
 }catch(e){notify(e.message,true);}});
app.addEventListener('keydown',event=>{const target=event.target;if(target.closest('.failure-preview'))return;if(target.matches('[data-cell],[data-terminal],[data-wire]')&&['Enter',' '].includes(event.key)){event.preventDefault();if(target.dataset.cell){S.selected=target.dataset.cell;S.ai=false;render();}else target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(target.id==='chat-input'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();ask(target.value);}});
window.addEventListener('keydown',event=>{if(dialog.open||event.target.matches('input,textarea,select,[contenteditable]'))return;if(event.key==='Escape'){if(tour.state.active){tour.dismiss();render();return;}S.pending=null;S.tool='select';S.selected=null;render();}if(S.doc&&S.view==='build'){if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='z'){event.preventDefault();action(event.shiftKey?'redo':'undo');}if(['Delete','Backspace'].includes(event.key)&&S.selected&&!S.selected.includes(':')){event.preventDefault();action('delete');}}});
window.addEventListener('beforeunload',e=>{if(S.dirty||S.saving){e.preventDefault();e.returnValue='';}});
(async()=>{try{const [session]=await Promise.all([workspaceFetch('/api/session').then(r=>r.json()),refreshCatalog()]);S.token=session.result.token;render();}catch(e){app.innerHTML=`<main class="empty-error"><h1>The workspace could not open</h1><p>${esc(e.message)}</p>${btn('reload','Try again','arrow','primary')}</main>`;app.querySelector('[data-act=reload]').onclick=()=>location.reload();}})();
